{"command": "cd /home/salboaie/work/sopworlds/soplang-nlu/eval-results/2026-11-28-vibe-batches/drawing && python3 - <<'EOF'
import csv,re
rows=list(csv.DictReader(open('objects-01-advanced.p01.csv')))
def parse(sop):
    ids={}; refs=set()
    for line in sop.splitlines():
        line=line.strip()
        if not line: continue
        m=re.match(r'@(\w+)\s+(\S+)(.*)$',line)
        ids[m.group(1)]=(m.group(2),m.group(3))
        for r in re.findall(r'\$(\w+)',m.group(3)): refs.add(r)
    return ids,refs
n_orph=0; c_orph=0
for r in rows:
    ids,refs=parse(r['sop'])
    orph=[k for k in ids if k not in refs]
    nom=[k for k in orph if ids[k][0]=='syntax.nominal']
    cl=[k for k in orph if ids[k][0]=='syntax.clause']
    if nom:
        n_orph+=1
        print('NOM', r['n'], r['text'][:70])
        for k in nom: print('   ',k,ids[k][1])
    if cl:
        c_orph+=1
print('rows with orphan nominal:',n_orph,' rows with orphan clause:',c_orph)
EOF"}

